query.sql:
openapi: 3.1.0
info: { title: ping, version: "1" }
paths:
  /ping:
    get:
      operationId: ping
      parameters:
        - { name: user, in: query, schema: { type: string, default: "anonymous" } }
        - { name: n, in: query, schema: { type: integer, minimum: 0, default: 1 } }
        - { name: tags, in: query, style: form, explode: false, schema: { type: array, items: { type: string } } }
      responses:
        "200":
          description: pong
          content: { application/json: { example: { pong: true } } }

query.transform:
-- rs: the item, here the query parameters, converted by their schemas (n is a
-- number, tags a list, defaults filled in)
store.rows = store.rows or {}
table.insert(store.rows, 1, { os.date("%H:%M:%S"), rs.user, rs.n, table.concat(rs.tags or {}, ",") })
while #store.rows > 10 do table.remove(store.rows) end
return { columns = { "at", "user", "n", "tags" }, rows = store.rows }
